for attempt in range(1, retries + 1):
    try:
        do_request()
        break  # 成功就离开循环
    except Exception:
        wait = 2 ** (attempt - 1)  # 1s → 2s → 4s → 8s ...
        time.sleep(wait)           # 给服务端喘息时间,别立刻再打

from openai import APITimeoutError, APIConnectionError

# 正确:子类(APITimeoutError)在前,父类(APIConnectionError)在后
try:
    ...
except APITimeoutError:
    return "请求超时"
except APIConnectionError:
    return "连接失败"

# 写反的话,超时永远落入"连接失败"分支,上面那个 except 是死代码
